using System.Security.Cryptography;
using Microsoft.EntityFrameworkCore;
using SMSMais.Data;
using SMSMais.Data.Entities;

namespace SMSMais.Api.Auth;

/// <summary>
/// Seed do cabeçalho institucional do laudo (CDT Maricá) como UMA imagem (banner
/// brasão | texto | SUS RJ, com borda), ocupando a largura da página
/// (width="100%"). Imagem única evita divergência entre o editor e o PDF.
/// Idempotente: não sobrescreve cabeçalho já configurado no painel.
/// </summary>
internal static class SeedCabecalhoLaudo
{
    private static readonly Guid BannerId = new("00000000-0000-0000-0000-00000000a007");

    // URL absoluta da API (o /midias mora na API, não no front; endpoint público).
    private const string CabecalhoHtml = """
<p style="text-align: center"><img src="https://api.smsmarica.online/midias/00000000-0000-0000-0000-00000000a007" width="100%"></p>
""";

    public static async Task GarantirAsync(SmsMaisDbContext db, CancellationToken ct)
    {
        if (!await db.Midias.AnyAsync(m => m.Id == BannerId, ct))
        {
            var bytes = Convert.FromBase64String(BannerPngBase64);
            db.Midias.Add(new Midia
            {
                Id = BannerId,
                NomeArquivo = "cabecalho-cdt.png",
                MimeType = "image/png",
                Conteudo = bytes,
                TamanhoBytes = bytes.Length,
                Largura = 1400,
                Altura = 200,
                Categoria = "laudo-cabecalho",
                HashSha256 = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(),
                CriadoEm = DateTime.UtcNow,
            });
            await db.SaveChangesAsync(ct);
        }

        var cfg = await db.LaudoConfiguracoes
            .FirstOrDefaultAsync(x => x.Id == LaudoConfiguracao.IdSingleton, ct);

        if (cfg is null)
        {
            db.LaudoConfiguracoes.Add(new LaudoConfiguracao
            {
                Id = LaudoConfiguracao.IdSingleton,
                CabecalhoHtml = CabecalhoHtml,
                CabecalhoJson = "{}",
                RodapeHtml = string.Empty,
                RodapeJson = "{}",
                AtualizadoEm = DateTime.UtcNow,
            });
            await db.SaveChangesAsync(ct);
        }
        else if (string.IsNullOrWhiteSpace(cfg.CabecalhoHtml))
        {
            cfg.CabecalhoHtml = CabecalhoHtml;
            cfg.AtualizadoEm = DateTime.UtcNow;
            await db.SaveChangesAsync(ct);
        }
    }

    private const string BannerPngBase64 = "";
}
